import React,{useMemo,useState} from 'react';
import {publicGiftUrl,qrMatrix,qrSvgPath,qrCanvas,canvasBlob,downloadBlob,copyQr,packageCardCanvas} from './package-qr.js';
import {displayCode} from './gift-utils.js';
export default function QrPanel({code,publicWebUrl,kind='tarjeta'}){
 const [busy,setBusy]=useState(false),[notice,setNotice]=useState(''),[error,setError]=useState('');
 const asset=useMemo(()=>{try{const url=publicGiftUrl(publicWebUrl,code,kind);const matrix=qrMatrix(url);return {url,size:matrix.size+8,path:qrSvgPath(matrix)};}catch(e){return {error:e.message};}},[code,publicWebUrl,kind]);
 const run=async job=>{setBusy(true);setNotice('');setError('');try{await job();}catch(e){setError(e.message||'No se pudo preparar el QR.');}finally{setBusy(false);}};
 if(asset.error)return <div className="qr-setup-note"><strong>QR para el paquete</strong><p>Configurá la dirección pública de tu web en este panel para generar un QR que se pueda abrir desde un celular.</p></div>;
 return <section className="package-qr"><div className="package-qr-image"><svg xmlns="http://www.w3.org/2000/svg" viewBox={`0 0 ${asset.size} ${asset.size}`} shapeRendering="crispEdges" role="img" aria-label={`QR de la tarjeta ${displayCode(code)}`}><rect width={asset.size} height={asset.size} fill="#ffffff"/><path d={asset.path} fill="#000000"/></svg><strong>{displayCode(code)}</strong></div><div className="package-qr-tools"><h3>Listo para acompañar el regalo.</h3><p>El QR abre esta misma tarjeta. Podés pegarlo en tu diseño o descargar una etiqueta completa para el paquete.</p><div className="gift-admin-actions"><button className="button primary" disabled={busy} onClick={()=>run(async()=>{await copyQr(asset.url);setNotice('QR copiado como imagen. Ya podés pegarlo en tu diseño.');})}>Copiar QR como imagen</button><button className="button outline" disabled={busy} onClick={()=>run(async()=>{downloadBlob(await canvasBlob(qrCanvas(asset.url)),`qr-${code}.png`);setNotice('QR preparado para descargar.');})}>Descargar QR PNG ↓</button><button className="button outline" disabled={busy} onClick={()=>run(async()=>{downloadBlob(await canvasBlob(packageCardCanvas(asset.url,code)),`tarjeta-paquete-${code}.png`);setNotice('Tarjeta del paquete preparada para descargar.');})}>Descargar tarjeta para el paquete ↓</button></div><label className="qr-destination">Destino del QR<input readOnly value={asset.url} onFocus={e=>e.target.select()}/></label><p className="gift-note">Mantené el margen blanco del QR y escaneá una prueba antes de imprimir la tanda.</p>{notice&&<p className="gift-notice" role="status">{notice}</p>}{error&&<p className="gift-notice gift-error" role="alert">{error}</p>}</div></section>;
}
